                continue
            sig = self.get(u, toks)
            nbrs = {o for o in self._lsh.query(sig) if self._lsh_sigs[o].jaccard(sig) >= threshold}
            self._lsh.insert(u, sig)
            self._lsh_sigs[u] = sig
            self._adj[u] = nbrs
            for o in nbrs:
                self._adj[o].add(u)
